import{A as e,B as t,L as n,U as r,V as i,et as a,it as o,pt as s}from"./chunks/framework.COrJTECx.js";import"./chunks/assets.dCN7278J.js";var c=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core/container.md","filePath":"core/container.md"}`),l={name:`core/container.md`};function u(e,c,l,u,d,f){let p=o(`PluginTabsTab`),m=o(`PluginTabs`);return a(),t(`div`,null,[c[3]||=i(`<h1><img src="data:image/svg+xml,%3csvg%20width='100%25'%20height='100%25'%20viewBox='0%200%2018%2018'%20version='1.1'%20xmlns='http://www.w3.org/2000/svg'%20xmlns:xlink='http://www.w3.org/1999/xlink'%20xml:space='preserve'%20xmlns:serif='http://www.serif.com/'%20style='fill-rule:evenodd;clip-rule:evenodd;stroke-linejoin:round;stroke-miterlimit:2;'%3e%3cg%20transform='matrix(1,0,0,1,-3,-3)'%3e%3cpath%20d='M19,3L5,3C3.89,3%203,3.89%203,5L3,19C3,20.097%203.903,21%205,21L19,21C20.097,21%2021,20.097%2021,19L21,5C21,3.89%2020.1,3%2019,3M19,5L19,19L5,19L5,5L19,5Z'%20style='fill:rgb(82,96,105);fill-rule:nonzero;'/%3e%3c/g%3e%3c/svg%3e" width="32" height="32"> Container </h1><p>Its a wrapper that when combined with Exit Activity, interrupts the children execution flow exiting the Container beforehand.</p><h3 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to “Usage”">​</a></h3><p>The <strong>Container</strong> activity has no effect if not combined with <strong>Exit</strong> activity.</p><p>With these two activities, we can avoid nested conditional Ifs or exit early from a workflow wrapped in a <strong>Container</strong>.</p><p>Consider the below code:</p><img src="/assets/container-demo.BA0hkcb_.png" class="light-only"><img src="/assets/container-demo-dark.CzIjKBkA.png" class="dark-only"><p>Only the messages <em>&quot;First&quot;</em> and <em>&quot;Third&quot;</em> will be printed out.</p><p>Based on its condition, the <strong>Exit</strong> activity tells to <strong>Container</strong> interrupt its execution. Then, the process flow continues to the next activity.</p><p>Below is an abstraction of what happens to the execution flow:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>+------------------------------------+</span></span>
<span class="line"><span>|             Container              |</span></span>
<span class="line"><span>|         +----------------+         |</span></span>
<span class="line"><span>|         |   Write Line   |         |</span></span>
<span class="line"><span>|         |    &quot;First&quot;     |         |</span></span>
<span class="line"><span>|         +-------+--------+         |</span></span>
<span class="line"><span>|                 v                  |</span></span>
<span class="line"><span>|         +----------------+         |</span></span>
<span class="line"><span>|  +----- |      Exit      |         |</span></span>
<span class="line"><span>|  |      +-------+--------+         |</span></span>
<span class="line"><span>|  |              v                  |</span></span>
<span class="line"><span>|  |      +----------------+         |</span></span>
<span class="line"><span>|  |      |   Write Line   |         |</span></span>
<span class="line"><span>|  |      |    &quot;Second&quot;    |         |</span></span>
<span class="line"><span>|  |      +----------------+         |</span></span>
<span class="line"><span>+--|---------------------------------+</span></span>
<span class="line"><span>   |              v</span></span>
<span class="line"><span>   |      +----------------+</span></span>
<span class="line"><span>   +----&gt; |   Write Line   |</span></span>
<span class="line"><span>          |    &quot;Third&quot;     |</span></span>
<span class="line"><span>          +----------------+</span></span></code></pre></div><p>Everything that is below the <strong>Exit</strong> activity and inside the <strong>Container</strong> will be ignored/skipped and the execution flow will continue to the next activity after the <strong>Container</strong>.</p><p>This is very useful to avoid nested Ifs or to exit early from a workflow when certain conditions are not met.</p><p>See below the different approaches for handling multiple nested conditions.</p>`,15),r(m,null,{default:s(()=>[r(p,{label:`Ifs in a Sequence`},{default:s(()=>[...c[0]||=[n(`img`,{src:`/assets/ifs-approach.D40_Fzzw.png`,class:`light-only`},null,-1),n(`img`,{src:`/assets/ifs-approach-dark.c63Q__qB.png`,class:`dark-only`},null,-1)]]),_:1}),r(p,{label:`Decisions in a Flow Chart`},{default:s(()=>[...c[1]||=[n(`img`,{src:`/assets/flowchart-approach.BELISsjH.png`,class:`light-only`},null,-1),n(`img`,{src:`/assets/flowchart-approach-dark.J72a1P04.png`,class:`dark-only`},null,-1)]]),_:1}),r(p,{label:`Container & Exit`},{default:s(()=>[...c[2]||=[n(`img`,{src:`/assets/container-approach.BBGUGOyv.png`,class:`light-only`},null,-1),n(`img`,{src:`/assets/container-approach-dark.CpTOE6w4.png`,class:`dark-only`},null,-1)]]),_:1})]),_:1}),c[4]||=n(`div`,{class:`info custom-block`},[n(`p`,{class:`custom-block-title`},`SEE ALSO`),n(`ul`,null,[n(`li`,null,[n(`a`,{href:`./exit.html`},`Exit`)])])],-1)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};